# split_paragraph :: 'Hi. There. How are you?'
import re

def split_paragraph(text):
    return [s.strip() for s in re.split(r'(?<=[.!?])\s+', text) if s.strip()]

if __name__ == '__main__':
    print(split_paragraph('Hi. There. How are you?'))

